@font-face {
  font-family: "MyDisplayFont";
  src: url("/fonts/mydisplayfont-bold.woff2") format("woff2"),
       url("/fonts/mydisplayfont-bold.woff") format("woff");
  font-weight: 700;
  font-style: normal;
  font-display: swap; /* Prioritize content with immediate fallback, then swap */
}

@font-face {
  font-family: "MyBodyFont";
  src: url("/fonts/mybodyfont-regular.woff2") format("woff2"),
       url("/fonts/mybodyfont-regular.woff") format("woff");
  font-weight: 400;
  font-style: normal;
  font-display: fallback; /* Short block period, then fallback, then swap */
}
